        "format": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "full",
          "description": "Email format to return (\"full\", \"metadata\", \"minimal\", \"raw\").",
          "title": "Format"
        }
      },
      "title": "gmail_find_email_args",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "query",
        "id",
        "label",
        "max_results",
        "include_spam_trash",
        "format"
